command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "5cdd28c0b7188730a4182f24932d3aaa901b9cae") { throw "main moved" }
Write-Host "NONVALIDATION_METADATA_GUARD_PASS"
git -C $env:GITHUB_WORKSPACE push origin --delete work/validation-churn-guards work/validation-churn-empty-evidence-fix
if ($LASTEXITCODE -ne 0) { throw "temporary work branch cleanup failed" }
Write-Host "VALIDATION_CHURN_WORK_BRANCHES_DELETED"
